/**
 * A line offering a reload when the device switches between touch and a
 * mouse after the page started: the page chose its controls, sticks or
 * mouse and keyboard, once, and only a reload chooses again. Nothing reloads
 * by itself, since that would lose whatever the visitor was doing; switching
 * back takes the line away.
 *
 * Loaded after the page has started, so none of it is in first paint.
 */
import { detectTouchPrimary, type DetectionWindow } from './deviceDetection';

export const SWITCH_LINE_ID = 'webverse-touch-switch';
export const SWITCH_WORDS = { toTouch: 'Reload for touch controls', toMouse: 'Reload for mouse and keyboard' } as const;

/** A window whose coarse-pointer answer can be watched. */
export interface WatchedWindow extends DetectionWindow {
  matchMedia?: (query: string) => { matches: boolean; addEventListener?: (type: 'change', listener: () => void) => void };
}

/**
 * Calls `changed` each time the answer of `detectTouchPrimary` flips, as on
 * a device that folds into a tablet or has a mouse plugged in. Does nothing
 * where the browser cannot watch, and never throws.
 */
export function watchTouchPrimary(win: WatchedWindow, changed: (touch: boolean) => void): void {
  try {
    const query = win.matchMedia?.('(pointer: coarse)');
    let last = detectTouchPrimary(win);
    query?.addEventListener?.('change', () => {
      const now = detectTouchPrimary(win);
      if (now === last) return;
      last = now;
      changed(now);
    });
  } catch {
    // Watching is a convenience: the page goes on with the controls it began with.
  }
}

const CSS =
  'position:fixed;left:50%;top:64px;transform:translateX(-50%);z-index:31;margin:0;padding:0;' +
  'font:14px/1.4 system-ui,sans-serif;';
const BUTTON_CSS =
  'padding:10px 16px;border-radius:22px;border:1px solid rgba(255,255,255,.35);background:rgba(20,20,24,.92);' +
  'color:#fff;font:inherit;cursor:pointer;touch-action:manipulation;';

/** Watches `win` and offers the reload on `doc` when its answer is no longer `startedTouch`. */
export function offerReloadOnSwitch(
  doc: Document,
  win: WatchedWindow & { location: { reload(): void } },
  startedTouch: boolean,
): void {
  watchTouchPrimary(win, (touch) => {
    doc.getElementById(SWITCH_LINE_ID)?.remove();
    if (touch === startedTouch) return;
    const line = doc.createElement('p');
    line.id = SWITCH_LINE_ID;
    line.style.cssText = CSS;
    const button = doc.createElement('button');
    button.type = 'button';
    button.style.cssText = BUTTON_CSS;
    button.textContent = touch ? SWITCH_WORDS.toTouch : SWITCH_WORDS.toMouse;
    button.addEventListener('click', () => win.location.reload());
    line.appendChild(button);
    doc.body.appendChild(line);
  });
}
